// ============================================================
//  UTILITY FUNCTIONS
// ============================================================

/** Get all unique categories from the dataset */
export function getCategories(): string[] {
  return [...new Set(GLOBAL_OPPORTUNITIES.map(o => o.type))].sort();
}

/** Get all unique countries from the dataset */
export function getCountries(): string[] {
  return [...new Set(GLOBAL_OPPORTUNITIES.map(o => o.country))].sort();
}

/** Get all unique regions from the dataset */
export function getRegions(): string[] {
  return [...new Set(GLOBAL_OPPORTUNITIES.map(o => o.region).filter(Boolean))].sort() as string[];
}

/** Get category counts for metrics */
export function getCategoryCounts(): Record<string, number> {
  const counts: Record<string, number> = {};
  GLOBAL_OPPORTUNITIES.forEach(o => {
    counts[o.type] = (counts[o.type] || 0) + 1;
  });
  return counts;
}

/** Get country counts for metrics */
export function getCountryCounts(): Record<string, number> {
  const counts: Record<string, number> = {};
  GLOBAL_OPPORTUNITIES.forEach(o => {
    counts[o.country] = (counts[o.country] || 0) + 1;
  });
  return counts;
}

/** Get total funding value across all opportunities */
export function getTotalFundingValue(): number {
  return GLOBAL_OPPORTUNITIES.reduce((sum, o) => sum + (o.fundingAmount || 0), 0);
}
